export const BODY: string = "\n<p>Base64 تصویر کو حروف اور عددوں کی لمبی سٹرنگ میں بدلنے کا طریقہ ہے، جسے متن کی طرح کہیں بھی لکھا جا سکتا ہے۔ یہ تصویر کو فائل کے بجائے متن بنا دیتا ہے، اور اسی لیے ڈویلپر اسے HTML اور CSS میں استعمال کرتے ہیں۔</p>\n<p>Base64 کمپریشن نہیں ہے: یہ تصویر کو چھوٹا نہیں کرتا، بلکہ اسے تقریباً ایک تہائی بڑا کر دیتا ہے۔ اس کے باوجود یہ چھوٹی تصویروں، جیسے آئیکن اور لوگو، کے لیے بہت کارآمد ہے، کیونکہ اس سے الگ فائل لوڈ کرنے کی ضرورت ختم ہو جاتی ہے۔</p>\n<p>یہ رہنما بتاتا ہے کہ Base64 کیسے کام کرتا ہے، اس کی اضافی قیمت کیا ہے، چار آؤٹ پٹ فارمیٹ کیا ہیں، اور اسے کب استعمال کریں اور کب نہ کریں۔ تبدیل کرنے کے لیے <a href=\"/ur/tasveer-ko-base64-mein-convert-karein/\">امیج ٹو Base64</a> کھولیں۔</p>\n<h2 id=\"what-is-base64\">Base64 کیا ہے؟</h2>\n<p>Base64 بائنری ڈیٹا کو متن میں بدلنے کا معیار ہے، جس میں صرف حروف، عدد اور چند علامتیں استعمال ہوتی ہیں۔ تصویر کے ہر تین بائٹ چار حروف بنتے ہیں، اس لیے نتیجہ لمبی سٹرنگ ہوتا ہے۔</p>\n<p>یہ سٹرنگ کہیں بھی لکھی جا سکتی ہے: HTML فائل، CSS فائل، ای میل یا API پیغام میں۔ جہاں صرف متن جا سکتا ہے، وہاں Base64 تصویر پہنچا دیتا ہے۔</p>\n<p>Base64 تصویر کو خفیہ نہیں کرتا: کوئی بھی سٹرنگ کو واپس تصویر میں بدل سکتا ہے۔ اسے سیکیورٹی کے لیے استعمال نہ کریں، صرف منتقلی کے لیے استعمال کریں۔</p>\n<h2 id=\"how-encoding-works\">Base64 انکوڈنگ کیسے کام کرتی ہے</h2>\n<p>انکوڈنگ تصویر کے بائٹس کو چھ بٹ کے گروپوں میں بانٹتی ہے، اور ہر گروپ کو ایک حرف سے بدل دیتی ہے۔ یہ عمل الٹا بھی ہو سکتا ہے، اس لیے سٹرنگ سے اصل تصویر بالکل واپس بن جاتی ہے۔</p>\n<p>یہ تبدیلی بغیر نقصان کے ہوتی ہے: انکوڈ اور ڈی کوڈ کرنے کے بعد تصویر بالکل ویسی ہی رہتی ہے، جیسی پہلے تھی۔ نہ رنگ بدلتے ہیں، نہ پکسلز کم ہوتے ہیں۔</p>\n<p>انکوڈنگ میں وقت لگتا ہے، مگر چھوٹی فائلوں کے لیے یہ لمحوں کا کام ہے۔ بڑی فائلوں کی سٹرنگ بہت لمبی ہو جاتی ہے، جسے سنبھالنا مشکل ہوتا ہے۔</p>\n<h2 id=\"the-33-percent-overhead\">33 فیصد اضافی قیمت</h2>\n<p>Base64 تصویر کو تقریباً 33 فیصد بڑا کر دیتا ہے، کیونکہ ہر تین بائٹ چار حروف بنتے ہیں۔ 75KB والی تصویر Base64 میں 100KB کی سٹرنگ بن جاتی ہے۔</p>\n<p>یہ اضافی قیمت چھوٹی تصویروں کے لیے قابل قبول ہے، کیونکہ الگ فائل لوڈ کرنے کی درخواست بچ جاتی ہے۔ لیکن بڑی تصویر کے لیے 33 فیصد اضافی بوجھ صفحہ کو سست کر دیتا ہے۔</p>\n<p>اس لیے اصول یہ ہے: صرف چھوٹی تصویریں، جیسے 10KB سے کم، Base64 میں بدلیں۔ بڑی تصویروں کو فائل کے طور پر ہی رکھیں۔</p>\n<h2 id=\"four-output-formats\">ایک ٹول میں چار آؤٹ پٹ فارمیٹ</h2>\n<p>ٹول چار طرح کی آؤٹ پٹ دیتا ہے: خام Base64 سٹرنگ، ڈیٹا URL، HTML تصویر کا ٹکڑا اور CSS کا url ٹکڑا۔ ہر فارمیٹ الگ کام کے لیے بنایا گیا ہے۔</p>\n<p>خام سٹرنگ API اور ڈیٹا بیس کے لیے ہے، ڈیٹا URL براؤزر میں براہ راست کھلتا ہے، HTML ٹکڑا ویب صفحے میں لگتا ہے، اور CSS ٹکڑا اسٹائل شیٹ میں استعمال ہوتا ہے۔</p>\n<p>غلط فارمیٹ چننے سے کوڈ کام نہیں کرتا، اس لیے اپنی ضرورت کے مطابق فارمیٹ چنیں۔ اگر شک ہو تو ڈیٹا URL سے شروع کریں، جو سب سے عام ہے۔</p>\n<h2 id=\"data-url-explained\">ڈیٹا URL کی وضاحت</h2>\n<p>ڈیٹا URL ایک ایسا لنک ہے جو فائل کے بجائے خود ڈیٹا رکھتا ہے۔ یہ data:image/png;base64, سے شروع ہوتا ہے، اور اس کے بعد سٹرنگ آتی ہے۔ براؤزر اسے عام تصویر کی طرح دکھاتا ہے۔</p>\n<p>ڈیٹا URL کو براؤزر کے ایڈریس بار میں بھی کھولا جا سکتا ہے، اور وہ تصویر دکھائے گا۔ یہ جانچنے کا تیز طریقہ ہے کہ انکوڈنگ درست ہوئی ہے یا نہیں۔</p>\n<p>ڈیٹا URL بہت لمبا ہوتا ہے، اس لیے اسے ای میل یا چیٹ میں نہ بھیجیں۔ یہ ویب صفحے کے کوڈ کے اندر استعمال کے لیے ہے۔</p>\n<h2 id=\"raw-base64-explained\">خام Base64 کی وضاحت</h2>\n<p>خام Base64 صرف سٹرنگ ہے، بغیر کسی سابقے کے۔ اسے ڈیٹا بیس میں محفوظ کیا جا سکتا ہے، API سے بھیجا جا سکتا ہے، یا پروگرام میں استعمال کیا جا سکتا ہے۔</p>\n<p>خام سٹرنگ کو تصویر میں بدلنے کے لیے اس کے ساتھ فارمیٹ کی معلومات بھی چاہیے ہوتی ہے، جیسے یہ PNG ہے یا JPG۔ اس معلومات کے بغیر سٹرنگ بے کار ہے۔</p>\n<p>خام سٹرنگ کو محفوظ کرتے وقت اسے مکمل نقل کریں: ایک حرف بھی چھوٹ جائے تو تصویر خراب ہو جاتی ہے۔</p>\n<h2 id=\"html-img-snippet\">HTML تصویر کا ٹکڑا</h2>\n<p>HTML ٹکڑا تیار شدہ img ٹیگ ہے، جس میں src کے اندر ڈیٹا URL لکھا ہوتا ہے۔ اسے کاپی کر کے ویب صفحے میں لگائیں، اور تصویر بغیر کسی فائل کے نظر آئے گی۔</p>\n<p>یہ ٹکڑا خاص طور پر ای میل ٹیمپلیٹ اور چھوٹے ویب صفحے کے لیے مفید ہے، جہاں الگ تصویر فائل رکھنا مشکل ہو۔ ٹکڑے میں alt متن بھی شامل ہوتا ہے، جو رسائی کے لیے ضروری ہے۔</p>\n<p>HTML ٹکڑا استعمال کرتے وقت صفحے کا سائز دیکھیں: بڑی تصویر کا ٹکڑا HTML فائل کو بہت بڑا کر دیتا ہے، جس سے ایڈیٹنگ مشکل ہو جاتی ہے۔</p>\n<h2 id=\"css-url-snippet\">CSS کا url ٹکڑا</h2>\n<p>CSS ٹکڑا background-image میں ڈیٹا URL لگاتا ہے، جس سے پس منظر کی تصویر بغیر فائل کے دکھائی دیتی ہے۔ یہ چھوٹے آئیکن اور پیٹرن کے لیے بہترین ہے۔</p>\n<p>CSS میں Base64 استعمال کرنے سے اسٹائل شیٹ بھاری ہو جاتی ہے، مگر تصویر کی درخواست بچ جاتی ہے۔ چھوٹے آئیکن کے لیے یہ تجارت فائدہ مند ہے۔</p>\n<p>CSS ٹکڑے کو الگ فائل میں رکھیں، تاکہ HTML صاف رہے۔ بڑی تصویر کا CSS ٹکڑا اسٹائل شیٹ کو سست کر دیتا ہے۔</p>\n<h2 id=\"quality-preservation\">معیار: انکوڈنگ کچھ نہیں بدلتی</h2>\n<p>Base64 انکوڈنگ تصویر کے معیار کو بالکل نہیں بدلتی، کیونکہ یہ کمپریشن نہیں، صرف تبدیلی ہے۔ انکوڈ اور ڈی کوڈ کے بعد تصویر بالکل اصل جیسی رہتی ہے۔</p>\n<p>لیکن فائل کا سائز بڑھ جاتا ہے، اس لیے Base64 کو معیار بچانے کا طریقہ نہ سمجھیں۔ یہ صرف منتقلی کا طریقہ ہے، بہتری کا نہیں۔</p>\n<p>اگر تصویر پہلے سے خراب ہے تو Base64 اسے ٹھیک نہیں کرے گا۔ پہلے معیار درست کریں، پھر انکوڈ کریں۔</p>\n<h2 id=\"supported-formats\">کون سے فارمیٹ اور سائز کام کرتے ہیں</h2>\n<p>ٹول JPG، PNG، WebP اور GIF فائلوں کو قبول کرتا ہے۔ ہر فارمیٹ کی سٹرنگ اسی فارمیٹ کی معلومات کے ساتھ بنتی ہے، تاکہ ڈی کوڈ کرتے وقت فارمیٹ معلوم رہے۔</p>\n<p>سائز کی حد براؤزر پر منحصر ہے، مگر عملی طور پر 10MB سے کم فائلیں آرام سے انکوڈ ہو جاتی ہیں۔ اس سے بڑی فائل کی سٹرنگ اتنی لمبی ہو جاتی ہے کہ براؤزر سست ہو جاتا ہے۔</p>\n<p>متحرک GIF بھی انکوڈ ہو جاتی ہے، اور ڈی کوڈ کرنے پر حرکت برقرار رہتی ہے۔ لیکن متحرک GIF کی سٹرنگ بہت لمبی ہوتی ہے، اس لیے اسے Base64 میں نہ بدلیں۔</p>\n<h2 id=\"when-to-embed\">Base64 تصویر کب ایمبیڈ کریں</h2>\n<p>Base64 اس وقت استعمال کریں جب تصویر بہت چھوٹی ہو، جیسے آئیکن، لوگو یا چھوٹا پیٹرن۔ ایسی تصویریں الگ فائل کے طور پر لوڈ کرنے سے زیادہ وقت لیتی ہیں، جتنا ان کا سائز ہے۔</p>\n<p>ای میل ٹیمپلیٹ میں بھی Base64 اچھا ہے، کیونکہ ای میل میں بیرونی تصویر اکثر بلاک ہو جاتی ہے۔ ایمبیڈ شدہ تصویر ہمیشہ دکھائی دیتی ہے۔</p>\n<p>ایک صفحے والی ویب سائٹ یا آف لائن دستاویز میں بھی Base64 کام آتا ہے، جہاں الگ فائل رکھنا ممکن نہیں ہوتا۔</p>\n<h2 id=\"when-not-to-embed\">کب ایمبیڈ نہ کریں</h2>\n<p>بڑی تصویروں کو کبھی Base64 میں نہ بدلیں۔ 500KB والی تصویر 665KB کی سٹرنگ بن جاتی ہے، جو صفحہ کو بہت سست کر دیتی ہے۔</p>\n<p>بار بار استعمال ہونے والی تصویر کو بھی فائل کے طور پر رکھیں، کیونکہ براؤزر فائل کو کیش کرتا ہے۔ Base64 سٹرنگ ہر صفحے پر دوبارہ ڈاؤن لوڈ ہوتی ہے، اس لیے کیش کا فائدہ ختم ہو جاتا ہے۔</p>\n<p>سرچ انجن بھی Base64 تصویروں کو عام تصویروں کی طرح نہیں دیکھتے، اس لیے اہم تصویر کو فائل کے طور پر رکھیں، تاکہ وہ تلاش میں آئے۔</p>\n<h2 id=\"email-and-api-use\">ای میل اور API میں Base64</h2>\n<p>ای میل میں Base64 تصویر کو اٹیچمنٹ کے بجائے متن میں بھیجتا ہے، جس سے وہ ہر ای میل کلائنٹ میں دکھائی دیتی ہے۔ چھوٹی لوگو یا دستخط کے لیے یہ بہترین طریقہ ہے۔</p>\n<p>API میں Base64 تصویر کو JSON پیغام میں بھیجتا ہے، جہاں بائنری فائل نہیں جا سکتی۔ موبائل ایپ تصویر کو Base64 میں بدل کر سرور کو بھیجتی ہے۔</p>\n<p>API میں بڑی تصویر Base64 میں بھیجنے سے پیغام بہت بڑا ہو جاتا ہے، اس لیے بڑی فائل کے لیے براہ راست اپ لوڈ کا طریقہ بہتر ہے۔</p>\n<h2 id=\"privacy-local-processing\">پرائیویسی: انکوڈنگ آپ کے براؤزر میں ہوتی ہے</h2>\n<p>انکوڈنگ آپ کے براؤزر میں ہوتی ہے، تصویر کسی سرور پر نہیں جاتی۔ یہ نجی تصویروں کے لیے بہت اہم ہے، کیونکہ فائل آپ کے آلے سے باہر نہیں نکلتی۔</p>\n<p>لیکن Base64 سٹرنگ خود تصویر ہے: اسے شیئر کرنے کا مطلب تصویر شیئر کرنا ہے۔ سٹرنگ کو عوامی جگہ، جیسے فورم یا چیٹ، میں نہ ڈالیں۔</p>\n<p>براؤزر بند کرنے پر ڈیٹا ختم ہو جاتا ہے، مگر کاپی کی گئی سٹرنگ آپ کے کلپ بورڈ میں رہتی ہے۔ کام ختم ہونے پر کلپ بورڈ صاف کر دیں۔</p>\n<h2 id=\"how-to-use-the-tool\">امیج ٹو Base64 ٹول کیسے استعمال کریں</h2>\n<p>تصویر ٹول میں ڈالیں، چار میں سے ایک آؤٹ پٹ فارمیٹ چنیں، اور سٹرنگ کاپی کریں۔ چھوٹی تصویر کے لیے ڈیٹا URL، اور API کے لیے خام سٹرنگ چنیں۔</p>\n<p>استعمال سے پہلے سٹرنگ کو براؤزر میں کھول کر جانچیں، تاکہ تصدیق ہو کہ تصویر درست انکوڈ ہوئی ہے۔ Base64 کب ایمبیڈ کریں، اس کی تفصیل <a href=\"/ur/blog/base64-tasveer-kab-embed-karein/\">Base64 تصویریں کب ایمبیڈ کریں</a> میں اور عملی مراحل <a href=\"/ur/blog/tasveer-ko-base64-mein-kaise-convert-karein/\">تصویر کو Base64 میں کیسے بدلیں</a> میں پڑھیں۔ واپس تصویر بنانی ہو تو <a href=\"/ur/base64-ko-tasveer-mein-convert-karein/\">Base64 ٹو امیج</a> استعمال کریں۔</p>\n";

